INSERT INTO "ParkMapMarker" ("id", "parkId", "type", "name", "latitude", "longitude", "source", "sourceRef", "license", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, p."id", v.type::"MapMarkerType", v.name, v.lat, v.lng, 'USFS Recreation Sites (EDW)', v.ref, 'Public domain (USFS)', now(), now()
FROM (SELECT "id" FROM "Park" WHERE "name" ILIKE '%brock creek%' ORDER BY ("status" = 'APPROVED') DESC, "createdAt" ASC LIMIT 1) p
CROSS JOIN (VALUES
    ('TRAILHEAD', 'Austin Trailhead', 35.53621, -92.80372, 'usfs:recsite/AUSTIN, BROCK CREEK OHV'),
    ('TRAILHEAD', 'Mountain Man Trailhead', 35.52992, -92.83932, 'usfs:recsite/MOUNTAIN MAN, BROCK CREEK OHV'),
    ('TRAILHEAD', 'Zing Trailhead', 35.51062, -92.81723, 'usfs:recsite/ZING, BROCK CREEK OHV'),
    ('CAMPGROUND', 'Brock Creek Campground', 35.51031, -92.81781, 'usfs:recsite/BROCK CREEK CG')
) AS v("type", "name", "lat", "lng", "ref");

INSERT INTO "ParkMapMarker" ("id", "parkId", "type", "name", "latitude", "longitude", "source", "sourceRef", "license", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, p."id", v.type::"MapMarkerType", v.name, v.lat, v.lng, 'USFS Recreation Sites (EDW)', v.ref, 'Public domain (USFS)', now(), now()
FROM (SELECT "id" FROM "Park" WHERE "name" ILIKE '%wolf pen%' ORDER BY ("status" = 'APPROVED') DESC, "createdAt" ASC LIMIT 1) p
